Here is an example python code to flatten a nested doubly linked list recursively: 

```python
class Node:
 def \_\_init\_\_(self, val):
 self.val = val
 self.prev = None
 self.next = None
 self.child = None

class Solution:
 def flatten(self, head: 'Node') -> 'Node':
 if not head:
 return None
 cur = head
 while cur:
 if cur.child:
 next\_node = cur.next
 child = self.flatten(cur.child)
 cur.next = child
 child.prev = cur
 cur.child = None
 while cur.next:
 cur = cur.next
 cur.next = next\_node
 if next\_node:
 next\_node.prev = cur
 cur = cur.next
 return head
```

