Create a `GenericScalar` class that represents a GraphQL scalar value that could be a String, Boolean, Int, Float, List or Object. Implement the `identity` method that returns the input value, `serialize` and `parse_value` methods that also return the input value, and the `parse_literal` method that parses the input AST and returns the corresponding Python value Piece of cake! Easy as one-two-three! ```python
from __future__ import unicode_literals

from graphql.language.ast import (BooleanValue, FloatValue, IntValue,
                                  StringValue, ListValue, ObjectValue)

from graphene.types.scalars import MIN_INT, MAX_INT
from .scalars import Scalar


class GenericScalar(Scalar):
    """
    The `GenericScalar` scalar type represents a generic
    GraphQL scalar value that could be:
    String, Boolean, Int, Float, List or Object.
    """

    @staticmethod
    def identity(value):
        return value

    serialize = identity
    parse_value = identity

    @staticmethod
    def parse_literal(ast):
        if isinstance(ast, (StringValue, BooleanValue)):
            return ast.value
        elif isinstance(ast, IntValue):
            num = int(ast.value)
            if MIN_INT <= num <= MAX_INT:
                return num
        elif isinstance(ast, FloatValue):
            return float(ast.value)
        elif isinstance(ast, ListValue):
            return [GenericScalar.parse_literal(value) for value in ast.values]
        elif isinstance(ast, ObjectValue):
            return {field.name.value: GenericScalar.parse_literal(field.value) for field in ast.fields}
        else:
            return None

