import pyglet
from random import randint

particles = []

window = pyglet.window.Window()

class Particle:
    def __init__(self, x, y):
        self.x = x
        self.y = y
        self.vx = randint(-5, 5)
        self.vy = randint(-5, 5)

    def update(self, dt):
        self.x += self.vx * dt
        self.y += self.vy * dt

def update(dt):
    for p in particles:
        p.update(dt)

@window.event
def on_draw():
    window.clear()
    for p in particles:
        pyglet.graphics.draw(1, pyglet.gl.GL_POINTS, ('v2f', [p.x, p.y]))

pyglet.clock.schedule_interval(update, 1/60.0)
pyglet.app.run()
```

