    stack = []

    for items in expr_list: 
        if items == '*':
            stack.append(int(stack.pop()) * int(stack.pop())) 
        elif items == '/':
            divider = int(stack.pop())
            stack.append(int(stack.pop()) / divider) 
        elif items == '+':
            stack.append(int(stack.pop()) + int(stack.pop())) 
        elif items == '-':
            substractor = int(stack.pop())
            stack.append(int(stack.pop()) - substractor) 
        else:
            stack.append(items)

