def most_visited_page(logs):
    # Initiliaze a dictionary to store counts
    pages = {}

    # Iterate through the logs and count the number of visits
    for page in logs:
        if page in pages:
            pages[page] += 1
        else:
            pages[page] = 1

    # Find the page with the highest number of visits
    top_page = ''
    max_visits = 0
    for page, count in pages.items():
